local a=peripheral.find("inventory")if not a or not peripheral.hasType(a,"inventory")then return nil end;local b=a;b.itemTypes={}b.index={}b.index.defaultMaxCount=64;b.index.isIndexed=false;b.index.latestLog={}function b.index.itemTypesCount()local c=0;for d in pairs(b.itemTypes)do c=c+1 end;return c end;function b.index.index()b.index.isIndexed=false;b.index.latestLog={"starting indexing ..."}local e=b.index.itemTypesCount()local f=b.list()for g,h in pairs(f)do if h and not b.itemTypes[h.name]then local i,details=pcall(b.getItemDetail,g)if i and details then b.itemTypes[h.name]={name=h.name,displayName=details.displayName,maxCount=details.maxCount}end;sleep(0)end;table.insert(b.index.latestLog,"indexing: "..math.floor(g/#f*100).."%")end;if b.index.itemTypesCount()>e then table.insert(b.index.latestLog,"saving index ...")if b.index.save()then table.insert(b.index.latestLog,"saved index successfully.")else table.insert(b.index.latestLog,"failted to saved index, probably no storage remaining.")end end;b.index.isIndexed=true;table.insert(b.index.latestLog,"indexed "..b.index.itemTypesCount().." unique items successfully.")end;b.index.savePath=".indexedDB"function b.index.save()print("[items indexer] saving index to disk ...")local j=fs.open(b.index.savePath,"w+")if not j then print("[items indexer] failed to save index.")return false end;j.write(textutils.serialise(b.itemTypes,{allow_repetitions=false,compact=true}))j.close()print("[items indexer] saved index to disk.")return true end;function b.index.load()b.index.isIndexed=false;print("[items indexer] loading index from disk ...")if not fs.exists(b.index.savePath)then print("[items indexer] failed to load index: not found.")return false end;local j=fs.open(b.index.savePath,"r")if not j then print("[items indexer] failed to load index: not sure.")return false end;b.itemTypes=textutils.unserialise(j.readAll()or"")or{}print("[items indexer] loaded index from disk.")j.close()b.index.isIndexed=true;return true end;functio